[787] = { en = "The New Horde", tier = 1,
  t = "De nieuwe Horde",
  d = "Throm'ka, $c. Ik ben Eitrigg. Thrall heeft me de taak gegeven om de training van de rekruten te leiden.$b$bDe Horde is veranderd. Ze is niet meer wat ze vroeger was. Er was een tijd dat ik de Horde verliet. Ik was teleurgesteld, want de machtsbeluste pionnen van de Burning Legion kregen steeds meer invloed. Tijdens mijn ballingschap namen mensen me gevangen, maar de Warchief heeft me gered. Hij vertelde me over zijn visie: een Horde zonder de invloed van demonen, geleid door de sjamanen. Toen kwam ik terug.$b$bGornek heeft meer instructies voor je.",
  o = "Meld je bij Gornek in de Den.",
  c = "Weer een rekruut van Eitrigg, hm?$B$BHet gaat slecht met ons als dit het beste is wat de Horde kan maken. Maakt niet uit. Als wij vinden dat je klaar bent om de Valley te verlaten, ben je een trotse krijger van de Horde.",
  g = { {"rekruten", "recruits (rekruut)"}, {"leiden", "to lead"}, {"teleurgesteld", "disappointed, disillusioned"}, {"machtsbeluste", "power-hungry (machtsbelust)"}, {"pionnen", "pawns (pion)"}, {"invloed", "influence"}, {"ballingschap", "exile"}, {"gevangen", "captured, prisoner"}, {"gered", "rescued (redden)"}, {"visie", "vision"}, {"sjamanen", "shamans (sjamaan)"}, {"rekruut", "recruit"}, {"verlaten", "to leave"}, {"trotse", "proud (trots)"} },
},

[4641] = { en = "Your Place In The World", tier = 1,
  t = "Jouw plek in de wereld",
  d = "Eindelijk ben je oud genoeg, $N... oud genoeg om te vechten in naam van de Horde. Om te veroveren voor de glorie van de Warchief.$B$BJa...$B$B<Kaltunk bekijkt je.>$B$BJij bent geschikt.$B$BJe wilt vast een grote draak of demon vinden en die met je blote handen wurgen. Maar misschien is het slim om met iets minder... gevaarlijks te beginnen.$B$B<Kaltunk lacht.>$B$BMeld je bij Gornek. Hij kan je vast een taak geven die beter past bij een jonge $c. Je vindt Gornek in de Den, in het westen.$b",
  o = "Spreek met Gornek. Je weet nog dat Kaltunk zijn plek op je kaart heeft aangegeven. Hij zei ook dat Gornek in de Den woont, een gebouw in het westen.",
  c = "Weer een rekruut van Kaltunk, hm?$B$BHet gaat slecht met ons als dit het beste is wat de Horde kan maken. Maakt niet uit. Als wij vinden dat je klaar bent om de Valley te verlaten, ben je een trotse $C van de Horde.",
  g = { {"eindelijk", "finally"}, {"veroveren", "to conquer"}, {"glorie", "glory"}, {"bekijkt", "looks over (bekijken)"}, {"geschikt", "suitable, will do"}, {"draak", "dragon"}, {"blote handen", "bare hands"}, {"wurgen", "to strangle"}, {"gevaarlijks", "dangerous (iets gevaarlijks)"}, {"aangegeven", "marked, indicated (aangeven)"}, {"gebouw", "building"}, {"rekruut", "recruit"} },
},

[5843] = { en = "Welcome!", tier = 1,
  t = "Welkom!",
  d = "Welkom in World of Warcraft!$B$BBedankt dat je de World of Warcraft Collector's Edition hebt gekocht. Als speciaal bedankje kun je deze cadeaubon inleveren bij Magga in de Valley of Trials. Dan krijg je een cadeau: een klein maatje dat met je meegaat op je zoektocht naar avontuur en glorie.$B$BNogmaals bedankt, en geniet van je verblijf in World of Warcraft!",
  o = "Breng de Valley of Trials Gift Voucher naar Magga.",
  p = "Hallo! Leuk je te ontmoeten!$B$BIk zie dat je een speciale bon hebt. Geef hem aan mij, dan bied ik je er iets voor terug.",
  c = "Je bent echt een speciale held, $N. Welkom in de wereld van Azeroth! We bieden je een van deze unieke cadeaus aan!",
  g = { {"bedankje", "token of thanks"}, {"cadeaubon", "gift voucher"}, {"inleveren", "to hand in"}, {"maatje", "buddy, companion"}, {"zoektocht", "quest, search"}, {"nogmaals", "once again"}, {"verblijf", "stay"}, {"bon", "voucher"}, {"bied", "offer (bieden)"}, {"unieke", "unique (uniek)"} },
},

[7664] = { en = "Ivory Raptor Replacement", tier = 1,
  t = "Vervanging van de Ivory Raptor",
  c = "Jij brengt mij je oude raptor, ik geef jou een nieuwe met pas geslepen klauwen! De nieuwe raptor is net zo snel als je oude, maar hij ziet er nieuw uit. Kijk maar naar de snelle raptors hier om te zien waar je uit kunt kiezen.",
