  t = "Vervanging van de Red Raptor",
  c = "Jij brengt mij je oude raptor, ik geef jou een nieuwe met pas geslepen klauwen! De nieuwe raptor is net zo snel als je oude, maar hij ziet er nieuw uit. Kijk maar naar de snelle raptors hier om te zien waar je uit kunt kiezen.",
