[788] = { en = "Cutting Teeth", tier = 1,
  t = "De eerste ervaring",
  d = "Eerst moet je wat meer ruggengraat krijgen. Ik kan je naar de Barrens sturen om op kodo's te jagen. Maar eerlijk gezegd ben je levend nuttiger voor ons dan dood.$b$bIk denk dat de gevlekte zwijnen ten noorden van hier een goede tegenstander voor je zijn.",
  o = "Dood 10 Mottled Boars en ga dan terug naar Gornek in de Den.",
  p = "Ik hoop dat je niet terug bent om me te overtuigen dat je je taak al hebt gedaan, $N? Nee, natuurlijk niet. Daarvoor heb ik een te goede mening over je.",
  c = "Hmmm, niet slecht, $N. Maar laat het je niet naar het hoofd stijgen... in je carrière vecht je nog tegen sterkere vijanden dan zwijnen.$b$bToch heb je jezelf goed bewezen. Je volgende proef is tegen een veel gevaarlijkere tegenstander, dus je hebt extra bescherming nodig.",
  g = { {"ruggengraat", "backbone, courage"}, {"eerlijk gezegd", "in all honesty"}, {"nuttiger", "more useful (nuttig)"}, {"gevlekte", "mottled, spotted (gevlekt)"}, {"zwijnen", "boars (zwijn)"}, {"tegenstander", "opponent"}, {"overtuigen", "to convince"}, {"mening", "opinion"}, {"laat het je niet naar het hoofd stijgen", "don't let it go to your head"}, {"bewezen", "proven (bewijzen)"}, {"proef", "trial, test"}, {"bescherming", "protection"} },
},

[789] = { en = "Sting of the Scorpid", tier = 1,
  t = "De angel van de scorpid",
  d = "Sterke krijgers en onhandige beginners zijn allebei al gevallen door de giftige angel van de scorpid. Ten noordwesten van hier vind je veel scorpids. Breng me tien van hun staarten. Dat is het bewijs dat je goed kunt vechten.$b$bHet tegengif voor hun steek wordt eigenlijk gemaakt van gif uit hun angels. We hebben altijd veel tegengif voor scorpidgif bij ons, om jonge strijders zoals jij te genezen...$b$bMaar dat heb jij vast niet nodig, toch?",
  o = "Haal 10 Scorpid Worker Tails voor Gornek in de Den.",
  p = "Het schild van een scorpid is niet zo dik dat een vastberaden $C erdoor wordt tegengehouden. Sla hard en zonder twijfel, dan zijn de scorpids een makkelijke prooi.",
  c = "Je moet een belangrijke les leren van het vechten tegen scorpids. De kleinste of de grootste tegenstander kan je toch de dood in sturen. In een fel gevecht kunnen heel veel dingen je ondergang zijn.$b$bIk kan je niets meer leren, $N. Je hebt het goed gedaan. Ik ga je vooruitgang met interesse volgen.",
  g = { {"angel", "sting, stinger"}, {"onhandige", "clumsy, awkward (onhandig)"}, {"giftige", "venomous (giftig)"}, {"staarten", "tails (staart)"}, {"bewijs", "proof"}, {"tegengif", "antidote"}, {"steek", "sting"}, {"gif", "venom, poison"}, {"genezen", "to heal"}, {"schild", "shell, carapace"}, {"vastberaden", "determined"}, {"tegengehouden", "stopped, deterred (tegenhouden)"}, {"prooi", "prey"}, {"fel", "fierce"}, {"ondergang", "downfall"} },
},

[4402] = { en = "Galgar's Cactus Apple Surprise", tier = 1,
  t = "Galgars cactusappelverrassing",
  d = "Het is echt heet hier in de Valley of Trials.$B$B<Galgar veegt zijn voorhoofd af.>$B$BAls ik maar wat cactusappels had! Dan kon ik mijn beroemde cactusappelverrassing maken! Niets koelt je sneller af dan een stuk van die heerlijke lekkernij.$B$BWeet je wat, $N? Als je me 10 cactusappels brengt, maak ik een paar porties cactusappelverrassing voor je. Die kun je meenemen op je avonturen. Heb je interesse? Cactusappels groeien bij de cactusplanten hier in de buurt.",
  o = "Breng Galgar 10 Cactus Apples. Je weet nog dat hij zei dat ze bij cactussen te vinden zijn.",
  p = "Ben je klaar met het verzamelen van cactusappels?",
  c = "Geweldig, $N! Zoals beloofd: hier is je cactusappelverrassing, en nog iets extra's.",
  g = { {"veegt", "wipes (afvegen)"}, {"voorhoofd", "forehead, brow"}, {"cactusappelverrassing", "cactus apple surprise"}, {"beroemde", "famous (beroemd)"}, {"koelt", "cools (afkoelen)"}, {"heerlijke", "delicious (heerlijk)"}, {"lekkernij", "treat, delicacy"}, {"porties", "portions (portie)"}, {"in de buurt", "nearby"}, {"verzamelen", "to collect"}, {"beloofd", "promised (beloven)"} },
},

[792] = { en = "Vile Familiars", tier = 1,
  t = "Gemene familiars",
  d = "Ik hoop dat je veel leert in de Valley of Trials, jonge $c.$B$BIk ben naar de Valley gestuurd om je te begeleiden. Maar ik heb hier een groeiende besmetting ontdekt...$B$BEen groep die zich de Burning Blade noemt, heeft hier in de Valley of Trials een heksenkring. Ze verstoppen zich in een grot in het noordoosten. Hun Vile Familiars zijn uit de opening van de grot gekomen en richten chaos aan.$B$BDit is je eerste taak tegen de Burning Blade: ik vraag je om deze familiars te verslaan. Dood er veel. Als je het overleeft, kom dan terug naar mij.",
  o = "Dood 12 Vile Familiars.$B$BGa terug naar Zureetha Fargaze buiten de Den.",
  p = "Om jezelf te bewijzen tegen de Burning Blade, moet je eerst de Vile Familiars verslaan. Kom terug als je dat gedaan hebt.",
  c = "Goed gedaan, $N.$b$bDe Vile Familiars waren maar huisdieren van de duistere machten in de Burning Blade. Toch voorspelt je succes tegen hen grotere daden in de toekomst.",
  g = { {"gemene", "vile, nasty (gemeen)"}, {"begeleiden", "to guide"}, {"besmetting", "taint, contamination"}, {"heksenkring", "coven"}, {"verstoppen zich", "are hiding (zich verstoppen)"}, {"opening", "mouth, opening"}, {"richten chaos aan", "cause havoc (chaos aanrichten)"}, {"verslaan", "to defeat"}, {"overleeft", "survive (overleven)"}, {"duistere", "dark (duister)"}, {"machten", "powers (macht)"}, {"voorspelt", "foretells (voorspellen)"}, {"daden", "deeds (daad)"} },
},

[5441] = { en = "Lazy Peons", tier = 1,
  t = "Luie peons",
  d = "Vervloekte peons! Ze werken hard. Ze halen hout van de bomen in de vallei. Maar ze doen altijd een dutje! Ik heb iemand nodig die de peons in het gareel houdt.$B$BJij lijkt me de juiste $r voor deze taak. Hier, neem deze knuppel. Gebruik hem op luie peons die je ziet slapen tijdens het werk. Een flinke klap, en ze gaan meteen weer aan het werk! Breng de knuppel terug als je klaar bent.$B$BWaardeloze, luie peons...",
  o = "Gebruik de Foreman's Blackjack op Lazy Peons als ze slapen. Maak 5 peons wakker en breng de Foreman's Blackjack dan terug naar Foreman Thazz'ril in de Valley of Trials.",
  p = "Waardeloze luie...$b$b Hè? Heb je mijn knuppel? Heb je peons betrapt die sliepen tijdens het werk?!",
  c = "Goed. Goed. Misschien denken ze de volgende keer twee keer na voordat ze gaan luieren! Bedankt voor je hulp!",
  o1 = "Peons gewekt",
  g = { {"vervloekte", "cursed (vervloekt)"}, {"hout", "wood, lumber"}, {"een dutje", "a nap"}, {"in het gareel houdt", "keeps in line (in het gareel houden)"}, {"knuppel", "club, blackjack"}, {"flinke", "good, hefty (flink)"}, {"klap", "smack, blow"}, {"waardeloze", "lousy, worthless (waardeloos)"}, {"betrapt", "caught (betrappen)"}, {"luieren", "to slack off"}, {"gewekt", "woken up (wekken)"} },
},

[6394] = { en = "Thazz'ril's Pick", tier = 1,
  t = "Thazz'rils houweel",
  d = "$N, jij bent een betrouwbare $r. Kan ik op je rekenen voor nog een taak?$B$BEen tijd geleden onderzocht ik de grot in het noorden. Ik zocht naar mineralen. Ik liet daar mijn favoriete houweel liggen. Later ging ik terug om hem te halen. Maar toen zat de grot vol met wrede beesten! Wil jij de grot in gaan, de Burning Blade Coven, en mijn houweel halen?$B$BIk heb hem achtergelaten in een ruimte met watervallen. Er zit een spreuk op mijn houweel, dus je kunt hem in het donker zien. Je hoeft je dus geen zorgen te maken over het vinden... alleen over wat hem bewaakt!",
  o = "Breng Thazz'ril's Pick naar Foreman Thazz'ril.",
  p = "Ben je in de Burning Blade Coven geweest, $N? Heb je mijn houweel gevonden?",
  c = "Geweldig, je hebt hem! Heel erg bedankt, $N. Dit is mijn favoriete houweel! Als mijn peons ooit klaar zijn met het omhakken van deze bomen, kunnen we misschien een mooie grot vinden voor de mijnbouw!",
  g = { {"houweel", "pick, pickaxe"}, {"betrouwbare", "dependable (betrouwbaar)"}, {"rekenen op", "to count on"}, {"onderzocht", "surveyed, examined (onderzoeken)"}, {"mineralen", "minerals (mineraal)"}, {"wrede", "vicious, cruel (wreed)"}, {"achtergelaten", "left behind (achterlaten)"}, {"ruimte", "room, chamber"}, {"watervallen", "waterfalls (waterval)"}, {"spreuk", "spell"}, {"bewaakt", "guards (bewaken)"}, {"omhakken", "to chop down"}, {"mijnbouw", "mining"} },
},

[790] = { en = "Sarkoth", tier = 1,
  t = "Sarkoth",
  d = "$C! Ik dacht dat ik hier zou sterven zonder dat iemand het wist. Ik jaagde op de scorpids van de Valley. Toen kwam ik een heel gemeen uitziende scorpid tegen. Ik viel hem aan en gaf hem een enorme klap op zijn klauw. Maar toen sloot die klauw zich om mijn been.$b$bOp zijn angel was ik niet voorbereid. Die sneed naar beneden, in mijn borst. Hij sneed in mijn vlees en liet me bloeden. Alsjeblieft, je moet de scorpid voor mij doden! Mijn eer moet bewaard blijven! Ik vocht met hem op de hoogvlakte in het zuiden.",
  o = "Dood Sarkoth en breng zijn klauw terug naar Hana'zua.",
  p = "Ahhh... mijn vader zei altijd dat ik nooit veel zou worden. En nu lig ik hier onder een boom, en mijn leven loopt langzaam weg. Ik ben bang dat hij gelijk had.$b$bIk wil tenminste sterven terwijl ik weet dat mijn laatste vijand dood is.",
  c = "Mijn klap was niet genoeg om hem te doden. Maar als ik zie hoeveel schade ik heb gedaan, ben ik toch een beetje trots. Als ik sterf, is dat kleine beetje trots alles wat ik heb om me sterk te houden. En als ik zo naar de korte lijst kijk van wat ik in mijn leven heb bereikt, word ik boos.",
  g = { {"sterven", "to die"}, {"gemeen uitziende", "vicious-looking"}, {"enorme", "massive (enorm)"}, {"klauw", "claw"}, {"voorbereid", "prepared, ready (voorbereiden)"}, {"sneed", "sliced, cut (snijden)"}, {"vlees", "flesh"}, {"bloeden", "to bleed"}, {"eer", "honor"}, {"bewaard blijven", "be upheld, be kept"}, {"hoogvlakte", "plateau"}, {"gelijk had", "was right (gelijk hebben)"}, {"tenminste", "at least"}, {"schade", "damage"}, {"bereikt", "accomplished (bereiken)"} },
},

[794] = { en = "Burning Blade Medallion", tier = 1,
  t = "Het Burning Blade-medaillon",
  d = "Door mijn waarzeggerij zie ik dat er diep in de Burning Blade Coven een voorwerp van macht verborgen is. Het wordt bewaakt door beesten en zwarte magie.$B$BHet heet het Burning Blade Medallion. Je volgende taak is om het te vinden en het uit de heksenkring weg te halen.$B$BMaar wees voorzichtig. Misschien is het medaillon in handen van een handlanger van de Burning Blade. Dan is die handlanger sterker dan de familiars die je al hebt ontmoet.$B$BGa, $N. Je vindt de heksenkring in een grot, in het noordwesten.",
  o = "Breng het Burning Blade Medallion naar Zureetha Fargaze, buiten The Den.",
  p = "Is je taak klaar, $N? Heb je het Burning Blade Medallion?",
  c = "Je hebt het gevonden! Goed gedaan!$b$bJouw werk in de Burning Blade Coven is heel belangrijk om deze sekte in de Valley of Trials uit te roeien. Maar ik ben bang dat ze nog meer plannen hebben in ons land.$b$bWe hebben het laatste van hen nog niet gezien.",
  g = { {"medaillon", "medallion"}, {"waarzeggerij", "divination"}, {"voorwerp", "item, object"}, {"verborgen", "hidden"}, {"bewaakt", "guarded (bewaken)"}, {"heksenkring", "coven"}, {"voorzichtig", "careful, wary"}, {"in handen van", "in the hands of"}, {"handlanger", "agent, henchman"}, {"ontmoet", "encountered, met (ontmoeten)"}, {"sekte", "cult"}, {"uit te roeien", "to root out (uitroeien)"} },
},

[804] = { en = "Sarkoth", tier = 1,
  t = "Sarkoth",
  d = "Wat je voor mij hebt gedaan, geeft me nieuwe moed. Ik mag niet zo makkelijk vallen! Ik moet volhouden!$b$bMaar ik kan de lange tocht terug naar de Den niet zonder hulp maken. Alsjeblieft, $n, ga terug naar de Den en vertel Gornek hoe het met me gaat. Misschien kan hij me helpen.",
  o = "Breng het nieuws over Hana'zua's nood naar Gornek in de Den.",
  c = "Zoals jij het beest beschrijft, moet het Sarkoth zijn! Geen wonder dat Hana'zua van hem verloor. We sturen meteen hulp naar hem. Je hoeft je geen zorgen meer te maken over Hana'zua.$b$bMaar ik moet zeggen: ik ben erg onder de indruk dat jij Sarkoth hebt gedood. Daar mag je trots op zijn, $N. En je vocht voor de eer van een vreemde, terwijl je ook andere taken had. Daardoor is jouw eigen eer nog groter geworden.",
  g = { {"moed", "courage"}, {"volhouden", "to endure, keep going"}, {"tocht", "trek, journey"}, {"nood", "plight, distress"}, {"beschrijft", "describe (beschrijven)"}, {"geen wonder", "no wonder"}, {"verloor", "lost (verliezen)"}, {"onder de indruk", "impressed"}, {"trots op", "proud of"}, {"vreemde", "stranger"}, {"eer", "honor"} },
},

[805] = { en = "Report to Sen'jin Village", tier = 1,
  t = "Meld je in Sen'jin Village",
  d = "Je proeven tegen de Burning Blade zijn voorbij... hier in de Valley. Maar ik wil dat je vertelt wat je hebt ontdekt.$B$BGa naar het trollendorp Sen'jin en zoek Master Gadrin. Om in Sen'jin Village te komen, ga je oostwaarts de vallei uit, en dan rechts bij de splitsing.$B$BVertel Gadrin over de Burning Blade, en dat ze de Valley of Trials hebben bereikt. Vraag hem of ze Sen'jin al hebben bereikt.$B$BGa, $N, en wees snel. Ik ben bang dat het kwaad uit de Burning Blade Coven maar een voorbode is van een groter gevaar...",
  o = "Spreek met Master Gadrin in Sen'jin Village.",
  c = "Hm... je bericht komt op een slecht moment. We zien de Burning Blade hier in Sen'jin niet. Maar hun kwaad heeft wortel geschoten voor de kust, op de Echo Isles.$b$bDe orcs zijn vrienden van de Darkspear Trolls. Eervolle vrienden. We willen de orcs helpen, maar... wij hebben ook hulp nodig.$b",
  g = { {"proeven", "trials (proef)"}, {"ontdekt", "discovered (ontdekken)"}, {"trollendorp", "troll village"}, {"oostwaarts", "eastward"}, {"splitsing", "fork (in the road)"}, {"bereikt", "reached (bereiken)"}, {"kwaad", "evil"}, {"voorbode", "herald, sign of what's coming"}, {"gevaar", "threat, danger"}, {"bericht", "report, message"}, {"heeft wortel geschoten", "has taken root (wortel schieten)"}, {"kust", "coast"}, {"eervolle", "honorable (eervol)"} },
},

[2161] = { en = "A Peon's Burden", tier = 1,
  t = "De last van een peon",
  d = "Pardon? Kun je me helpen?$B$BIk heb hier een lading eten. Ik liep over de weg en ik heb scorpids en spinnen en nog erger getrotseerd! Ik bracht het eten naar de Valley of Trials, want ik dacht dat ze het nodig hadden. En ik help graag. Maar ze hebben geen eten nodig! Nu moet ik het terugbrengen naar Razor Hill, en ik ben bang voor alle beesten onderweg...$B$BKun jij het voor me brengen? Ik ben maar een peon, maar jij bent een held. Jij bent nergens bang voor!$B$BBreng het naar Innkeeper Grosk in de herberg van Razor Hill. Dank je wel!",
  o = "Breng Ukor's Burden naar Innkeeper Grosk in Razor Hill.",
  p = "Welkom in Razor Hill!",
  c = "Ah, dit is het eten dat Ukor naar de Valley of Trials heeft gebracht. Hadden ze het niet nodig? Nou, ik denk dat ze jullie helden in opleiding graag laten hongeren. Dat is goed voor je karakter, zeggen ze!$b$bBedankt dat je het eten hebt teruggebracht. Ik zet het weer in de kast... maar hier, laat me je eerst iets verfrissends aanbieden!$b$bEn vergeet niet om hier in de herberg te rusten. Je bent misschien een dappere $C die klaar is voor de hele wereld. Maar als je geen energie meer hebt, heb je daar zelf niet veel aan, en de Horde ook niet.",
  g = { {"last", "burden, load"}, {"lading", "load"}, {"spinnen", "spiders (spin)"}, {"getrotseerd", "braved (trotseren)"}, {"terugbrengen", "to take back"}, {"onderweg", "along the way"}, {"herberg", "inn"}, {"in opleiding", "in training"}, {"hongeren", "to starve"}, {"karakter", "character, spirit"}, {"kast", "cupboard, shelves"}, {"iets verfrissends", "some refreshment"}, {"aanbieden", "to offer"}, {"rusten", "to rest"}, {"dappere", "brave (dapper)"} },
},

[784] = { en = "Vanquish the Betrayers", tier = 1,
  t = "Versla de verraders",
  d = "Onder leiding van Admiral Proudmoore zijn de mensen van Kul Tiras Durotar binnengevallen. Zo braken ze het verdrag dat de Warchief met Jaina Proudmoore had gesloten. Dat verdrag was jaren geleden nodig om Archimonde te verslaan.$b$bDe aanval van de mensen werd teruggeslagen, en Tiragarde Keep viel. Maar kort geleden hebben de reservetroepen van de Admiral de burcht weer veroverd. Ze worden geleid door Lieutenant Benedict. Weer vormen ze een gevaar voor ons thuisland. Deze mensen hebben geen respect voor diplomatie.$b$bBewijs je eer en reis naar het zuiden, naar Tiragarde Keep. Maak een einde aan de menselijke indringers.",
  o = "Dood 10 Kul Tiras Sailors, 8 Kul Tiras Marines en Lieutenant Benedict en ga terug naar Gar'Thok in Razor Hill.",
  p = "Je hebt je bevelen, $N. De veiligheid van Durotar staat op het spel. Doe je taak, of laat je hoofd hangen van schaamte.$B$BLaat je eer zien en versla de mensen van Tiragarde Keep.",
  c = "Het nieuws over je moed gaat snel rond, $C. In Orgrimmar zullen de verhalen over je overwinning bij Tiragarde Keep worden verkondigd.",
  g = { {"verraders", "betrayers (verrader)"}, {"onder leiding van", "led by"}, {"binnengevallen", "invaded (binnenvallen)"}, {"braken", "broke, violated (breken)"}, {"verdrag", "pact, treaty"}, {"gesloten", "made (a pact) (sluiten)"}, {"teruggeslagen", "repelled (terugslaan)"}, {"reservetroepen", "reserves"}, {"burcht", "keep, castle"}, {"veroverd", "taken, conquered (veroveren)"}, {"thuisland", "homeland"}, {"indringers", "invaders (indringer)"}, {"bevelen", "orders (bevel)"}, {"staat op het spel", "is at stake"}, {"schaamte", "shame"}, {"verkondigd", "proclaimed, heralded (verkondigen)"} },
},

[791] = { en = "Carry Your Weight", tier = 1,
  t = "Draag je eigen gewicht",
  d = "Door mijn leeftijd ben ik nutteloos in de strijd. Nu maak ik me op andere manieren nuttig.$b$bVanaf deze uitkijkpost let ik op indringers. Onze kracht hier groeit, dus ik blaas steeds minder vaak op de signaalhoorn.$b$bOm de tijd te doden maak ik spullen. Die helpen jongere, sterkere krijgers om ons thuisland te verdedigen.$b$bVoor jou kan ik een tas maken voor je spullen. Heb je iets aan zo'n tas? Breng me dan wat canvas. Dat materiaal hebben de mensen en de centauren vaak.",
  o = "Furl Scornbrow in de wachttoren van Razor Hill wil 8 Canvas Scraps.",
  p = "Ik vocht trots naast de Warchief toen we dit land als eersten in bezit namen. De littekens van de strijd staan op mijn huid.$b$bDe eer van de Horde is bewaard gebleven met de hulp van mijn bijl en mijn strijdkreet, bij de nederlaag van Archimonde. Toen werd uit nood het onheilige bondgenootschap met de mensen en de elfen gesloten.$b$bMaar mijn taak als wachter en leverancier geeft me een nieuw gevoel van waarde.",
  c = "Uitstekend, $N. Elke goede $C heeft vast iets aan deze tas op het slagveld.$b$bIk groet je energie en je bereidheid om te sterven in naam van de Horde!",
  g = { {"gewicht", "weight"}, {"nutteloos", "useless"}, {"uitkijkpost", "vantage point, lookout"}, {"indringers", "invaders (indringer)"}, {"signaalhoorn", "signal horn"}, {"de tijd te doden", "to pass the time (de tijd doden)"}, {"verdedigen", "to defend"}, {"centauren", "centaurs (centaur)"}, {"in bezit namen", "took possession of (in bezit nemen)"}, {"littekens", "scars (litteken)"}, {"strijdkreet", "battle cry"}, {"nederlaag", "defeat"}, {"onheilige", "unholy (onheilig)"}, {"bondgenootschap", "alliance"}, {"leverancier", "provider, supplier"}, {"slagveld", "battlefield"}, {"bereidheid", "willingness"} },
},

[818] = { en = "A Solvent Spirit", tier = 1,
  t = "Een oplossende geest",
  d = "Mijn ogen worden slechter, maar ik zie nog genoeg. Steeds vaker moet ik mijn kennis van alchemie gebruiken om me te helpen bij magie. Vroeger ging die magie heel makkelijk. Maar ik wil geen leerling nemen. Er is nog nooit een trol of orc gekomen die dat waard was.$B$BBen jij het waard? Ja, natuurlijk ben je dat... natuurlijk denk je dat je het bent.$B$BIk heb een paar dingen nodig. Wil je ze voor me halen?$B$BIk heb hele makrura-ogen nodig, en flesjes slijm van crawlers. Je vindt ze op elke makrura of crawler in Durotar. We spreken elkaar snel weer.",
  o = "Breng 4 Intact Makrura Eyes en 8 flesjes Crawler Mucus naar Master Vornal in Sen'jin Village.",
  p = "Tijd is de echte test van je kracht en je wil. Verlies je geduld of geef je toe aan zwakte, dan laat je zien wie je echt bent.",
  c = "Goed gedaan, jongeling... heel goed gedaan.",
  g = { {"oplossende", "solvent, dissolving (oplossen)"}, {"kennis", "knowledge, skill"}, {"alchemie", "alchemy"}, {"leerling", "apprentice"}, {"waard", "worthy"}, {"hele", "whole, intact (heel)"}, {"flesjes", "vials, little bottles (flesje)"}, {"slijm", "mucus, slime"}, {"geduld", "patience"}, {"geef je toe aan", "give in to (toegeven aan)"}, {"zwakte", "weakness"}, {"jongeling", "young one"} },
},

[823] = { en = "Report to Orgnil", tier = 1,
  t = "Meld je bij Orgnil",
  d = "Wij in Sen'jin Village hebben ook onze eigen problemen, en we danken je voor je hulp. Maar je nieuws over de Burning Blade kan voor iedereen problemen geven.$B$BIn Razor Hill werkt een orc, Orgnil Soulscar. Hij bewaakt Durotar tegen kwaad zoals de Burning Blade! Ga naar Orgnil en vertel hem over onze nood, en ook over je nieuws uit de Valley of Trials. Dat wil hij graag weten.$B$BRazor Hill ligt in het noorden.",
  o = "Spreek met Orgnil Soulscar in Razor Hill.",
  c = "Ja? Heb je iets te melden? Nou, vertel maar!",
  g = { {"eigen", "own"}, {"danken", "to thank"}, {"bewaakt", "guards, polices (bewaken)"}, {"kwaad", "evil"}, {"nood", "plight, distress"}, {"ligt", "lies, is located (liggen)"}, {"melden", "to report"} },
},

[831] = { en = "The Admiral's Orders", tier = 1,
  t = "De bevelen van de Admiral",
  d = "Mensen kun je niet vertrouwen. We vochten naast hen met een zwaar hart, want we wisten dat ze ons ooit zouden verraden.$b$bDe dood van Admiral Proudmoore was niet genoeg om zijn erfenis van bedrog te stoppen. Dat menselijke tuig had zijn plannen al goed klaar voordat hij stierf.$b$bHet lijkt erop dat zijn macht niet eens met Benedict sterft. Wie weet hoe lang het duurt voordat de volgende golven mannen van Proudmoore op onze kusten landen.$b$bDeze bevelen moeten meteen naar Nazgrel in Orgrimmar! Je vindt hem in de zaal van Thrall.",
  o = "Breng Admiral Proudmoore's Orders naar Nazgrel in de zaal van Thrall in Orgrimmar.",
  p = "Zie je niet dat ik het druk heb? Dit moet wel dringend zijn....",
  c = "Talloze keren heb ik de Warchief aangeraden om de mensen niet te vertrouwen. Maar het gaat hier niet om mijn eigen trots.$b$bJe hebt de Horde met eer gediend, jonge $C.$b$bEn nu moet je me excuseren. Ik moet Thrall meteen advies geven over deze zaken....",
  g = { {"bevelen", "orders (bevel)"}, {"vertrouwen", "to trust"}, {"met een zwaar hart", "with a heavy heart"}, {"verraden", "to betray"}, {"erfenis", "legacy"}, {"bedrog", "deceit"}, {"tuig", "scum"}, {"stierf", "died (sterven)"}, {"golven", "waves (golf)"}, {"kusten", "shores, coasts (kust)"}, {"zaal", "hall, chamber"}, {"dringend", "pressing, urgent"}, {"talloze", "countless (talloos)"}, {"aangeraden", "advised, urged (aanraden)"}, {"gediend", "served (dienen)"}, {"zaken", "matters (zaak)"} },
},

[786] = { en = "Thwarting Kolkar Aggression", tier = 1,
  t = "De aanval van de Kolkar stoppen",
  d = "Praat zachter, $c. De Kolkar-centauren zitten vlak achter de heuvelrug in het westen, in Kolkar Crag.$b$bGisternacht waren ze op rooftocht. Toen ben ik hun dorp binnengeslopen. Ik ontdekte dat die vieze beesten een aanval in drie delen hebben gepland op de trollen en orcs van Durotar.$b$bWe mogen hun invasie niet laten slagen. Misschien heb jij de kracht om Kolkar Crag binnen te dringen en hun aanvalsplannen te vernietigen.$b$bToen ik ze voor het laatst zag, hadden ze de plannen verdeeld over drie van hun leiders.",
  o = "Lar Prowltusk buiten Sen'jin Village wil dat je de 3 sets Attack Plans in Kolkar Crag vernietigt.",
  p = "De centauren zijn steeds weer een plaag voor de Horde. We kunnen niet toestaan dat ze ons thuisland willen belegeren.",
  c = "De Horde zou zeker winnen als de Kolkar-centauren aanvielen. Maar door zo'n aanval te voorkomen, hebben we onze machtige krijgers onnodig bloedvergieten bespaard.$B$BEn zo zeker als er zand is in de woestijn van Tanaris, weten we dat er bloed zal vloeien voordat deze zware tijden voorbij zijn.$B$BJe hebt je volk goed gediend, $C.",
  o1 = "Attack Plan: Valley of Trials vernietigd",
  o2 = "Attack Plan: Sen'jin Village vernietigd",
  o3 = "Attack Plan: Orgrimmar vernietigd",
  g = { {"zachter", "quieter, softer (zacht)"}, {"heuvelrug", "ridge"}, {"op rooftocht", "raiding"}, {"binnengeslopen", "snuck in (binnensluipen)"}, {"slagen", "to succeed"}, {"binnen te dringen", "to infiltrate (binnendringen)"}, {"vernietigen", "to destroy"}, {"verdeeld", "divided (verdelen)"}, {"plaag", "nuisance, plague"}, {"toestaan", "to allow, tolerate"}, {"belegeren", "to besiege"}, {"voorkomen", "to prevent"}, {"bloedvergieten", "bloodshed"}, {"bespaard", "spared (besparen)"}, {"vloeien", "to flow, be spilled"}, {"gediend", "served (dienen)"} },
},

[815] = { en = "Break a Few Eggs", tier = 1,
  t = "Een paar eieren breken",
  d = "Bah! Ik was bijna vergeten dat ik het ontbijt moet klaarmaken.$B$B$N, schiet op en haal een paar taillasher-eieren voor me. Ik heb er minstens drie nodig, anders heb ik niet genoeg voor de maaltijd van morgen.$B$BDe Bloodtalon Taillashers kunnen fel zijn. Ze beschermen hun eieren meestal tot de dood. Soms graven ze hun eieren te diep in de grond om ze veilig op te graven. Maar als je naar de Echo Isles gaat, ten zuidoosten van Sen'jin Village, vind je ze meestal overal op die eilanden.",
  o = "Breng 3 Taillasher Eggs naar Cook Torka in Razor Hill.",
  p = "Ontbijt, lunch, avondeten! Wat maakt het uit welke maaltijd het is? Iemand moet het toch koken - en dat ben ik!",
  c = "Je bent misschien zwak, maar je bent tenminste niet onhandig, $N.$b$bHier, neem dit en ga uit de weg. Ik moet koken.",
  g = { {"eieren", "eggs (ei)"}, {"klaarmaken", "to prepare, get ready"}, {"schiet op", "hurry up (opschieten)"}, {"minstens", "at least"}, {"maaltijd", "meal"}, {"fel", "fierce"}, {"beschermen", "to protect"}, {"graven", "bury, dig (graven)"}, {"op te graven", "to dig up (opgraven)"}, {"eilanden", "islands (eiland)"}, {"wat maakt het uit", "who cares"}, {"onhandig", "clumsy"} },
},

[817] = { en = "Practical Prey", tier = 1,
  t = "Nuttige prooi",
  d = "Veel van de huiden die we gebruiken komen van tijgers uit Durotar, $N. Dekens, harnassen, tenten: er zijn heel veel redenen om op de beesten te jagen. En er zijn ook veel redenen om ze tegelijk goed te laten leven en groeien.$B$BHet is tijd om de kudde wat uit te dunnen, om het zo te zeggen. We worden met steeds meer, en wat we nodig hebben wordt meer dan onze voorraad. Ik heb meer huiden nodig om goede spullen voor ons volk te maken.$B$BBreng me 4 tijgervachten uit Durotar, dan krijg je een beloning. Je vindt ze op de eilanden ten zuiden van hier.",
  o = "Breng 4 Durotar Tiger Furs naar Vel'rin Fang in Sen'jin Village.",
  p = "Ik weet nog hoe ik voor het eerst op tijgers jaagde, $N. Ik koos ervoor om te jagen op de grootste van de Echo Isles. Ik zat bijna een hele dag heel stil in de schaduw van de planten... ik keek... ik wachtte.$b$bMijn spieren waren gespannen, en ik was klaar om toe te slaan. Het was een van mijn grootste overwinningen toen die tijger eindelijk toehapte.",
  c = "Ik ben blij, $N. Dankzij jouw hulp wordt ons volk beschermd, en hebben ze het niet koud als de seizoenen veranderen.$b$bDank je.",
  g = { {"prooi", "prey"}, {"huiden", "hides (huid)"}, {"dekens", "blankets (deken)"}, {"harnassen", "armor (harnas)"}, {"tegelijk", "at the same time"}, {"kudde", "flock, herd"}, {"uit te dunnen", "to cull, thin out (uitdunnen)"}, {"om het zo te zeggen", "so to speak"}, {"voorraad", "stock, supply"}, {"tijgervachten", "tiger furs (tijgervacht)"}, {"beloning", "reward"}, {"schaduw", "shadow"}, {"gespannen", "taut, tense"}, {"toe te slaan", "to strike (toeslaan)"}, {"toehapte", "took the bait (toehappen)"} },
},

[825] = { en = "From The Wreckage....", tier = 1,
  t = "Uit het wrak....",
  d = "Een van mijn meest oplettende verkenners brengt nieuws. Het wrak van Proudmoores vloot ligt nog steeds voor de kust van Durotar, vlak ten oosten van Tiragarde Keep.$b$bHet is geen geheim dat de mensen veel weten van techniek. Ze werken samen met die vieze kleine wezens die gnomen heten. We moeten al onze mogelijke vijanden helemaal begrijpen. En ons volk heeft ook iets aan deze nieuwe kennis.$b$bZwem door het wrak, $n, en haal de werktuigen van de Alliance voor me op.",
  o = "Gar'Thok van Razor Hill wil dat je 3 Gnomish Tools uit het wrak voor de kust haalt.",
  p = "Als we eenmaal weten hoe de mensen hun vreemde machines bedienen, hebben we een grotere kans om ze te verslaan in toekomstige gevechten.$b$bMet onze nieuwe kennis kan de Horde alleen maar sterker worden.",
  c = "Je missie was een succes, $C. Ik zorg ervoor dat deze werktuigen met de volgende karavaan naar Orgrimmar gaan.$b$bGoed gedaan.",
  g = { {"wrak", "wreckage"}, {"oplettende", "observant (oplettend)"}, {"verkenners", "scouts (verkenner)"}, {"vloot", "fleet"}, {"geheim", "secret"}, {"techniek", "mechanics, technology"}, {"wezens", "creatures (wezen)"}, {"gnomen", "gnomes (gnoom)"}, {"kennis", "knowledge"}, {"werktuigen", "tools (werktuig)"}, {"als we eenmaal", "once we"}, {"bedienen", "to operate"}, {"toekomstige", "future (toekomstig)"}, {"karavaan", "caravan"} },
},

[808] = { en = "Minshina's Skull", tier = 1,
  t = "Minshina's schedel",
  d = "Ik hoor de stem van mijn broer, Minshina. Hij roept me in mijn dromen.$B$BHij is meegenomen door Zalazane, de heksenmeester op de Echo Isles in het oosten. En hij is dood.$B$BMaar de dood betekent geen vrijheid voor mijn broer. Zalazane heeft Minshina's geest met magie gevangen in zijn eigen schedel. In mijn dromen zie ik de schedel bij andere schedels, in een cirkel van macht op het grootste Echo Isle. Zolang hij daar blijft, is de ziel van mijn broer verdoemd.$B$BAlsjeblieft, $N. Zoek de cirkel en haal Minshina's schedel. Breng hem naar mij.$B$BBevrijd hem!",
  o = "Haal Minshina's Skull uit de cirkel van macht op de Echo Isles.$B$BBreng hem naar Master Gadrin in Sen'jin Village.",
  p = "Heb je de schedel van mijn broer, $N? Is hij eindelijk vrij?",
  c = "Dank je, $N. Je hebt Minshina gered. Je hebt de geest van mijn broer uit de slavernij gered!",
  g = { {"schedel", "skull"}, {"stem", "voice"}, {"dromen", "dreams (droom)"}, {"meegenomen", "taken (meenemen)"}, {"heksenmeester", "warlock"}, {"vrijheid", "freedom"}, {"geest", "spirit"}, {"gevangen", "trapped (vangen)"}, {"cirkel van macht", "circle of power"}, {"zolang", "as long as"}, {"ziel", "soul"}, {"verdoemd", "doomed"}, {"bevrijd", "free (bevrijden)"}, {"slavernij", "slavery"} },
},

})

